using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Joins a group call of an active live story. Returns join response payload for tgcalls
    /// </summary>
    public Task<TdLib.TdApi.Objects.Text> JoinLiveStoryAsync(int groupCallId = default, GroupCallJoinParameters joinParameters = default)
    {

           using var activity =  StartCallActivity("JoinLiveStoryAsync", typeof(JoinLiveStory).FullName ?? "JoinLiveStoryAsync");

           try
           {
             return client.JoinLiveStoryAsync(groupCallId, joinParameters);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
